1. function solve(l, r) {
2.   if (l == r) return 0;
3.   for (i = l; i < r; i++) {
4.     leftSum = sum(l, i); rightSum = sum(i+1, r);
5.     if (leftSum < rightSum) score = leftSum + solve(l, i);
6.     else if (leftSum > rightSum) score = rightSum + solve(i+1, r);
7.     else score = max(solve(l, i), solve(i+1, r)) + leftSum;
8.     maxScore = max(maxScore, score);
9.   }
10.  return maxScore;
11. }
